 function fence(cx,cy,angle,len){const id=fenceId++,n=Math.max(2,Math.round(len/24));for(let i=0;i<=n;i++){const f=i/n-.5;addOb({kind:'fence',x:cx+Math.cos(angle)*len*f,y:cy+Math.sin(angle)*len*f,radius:10,low:true,fenceId:id,idx:i,angle})}}
 function hayRow(cx,cy,angle,count){for(let i=0;i<count;i++){const f=i-(count-1)/2;addOb({kind:'hay',x:cx+Math.cos(angle)*f*44,y:cy+Math.sin(angle)*f*44,radius:21,low:true,angle})}}
 function log(cx,cy,angle){addOb({kind:'log',x:cx,y:cy,radius:16,low:true,angle,len:3});for(const f of [-1,1])addOb({kind:'logpart',x:cx+Math.cos(angle)*f*30,y:cy+Math.sin(angle)*f*30,radius:15,low:true})}
 function rock(x,y,r,cover=false){if(free(x,y,r))addOb({kind:'rock',x,y,radius:r,s:r*1.4,cover,seed:(x*7+y*13)%17})}
 function tree(x,y,s=1){if(free(x,y,14))addOb({kind:'tree',x,y,radius:14,s,seed:(x*3+y*11)%23,variant:Math.floor((x+y)/37)%3})}
 // Cover boulders right next to the henhouse.
