 for(const side of [-1,1]){const cx=H.x+side*585,cy=H.y-20;rock(cx,cy-70,26);rock(cx+side*22,cy+8,22);rock(cx-side*8,cy+82,24)}
 for(const [x,y,a] of [[H.x-260,H.y-470,.2],[H.x+270,H.y-460,-.25],[H.x-300,H.y+420,-.15],[H.x+310,H.y+410,.3]])log(x,y,a);
