 for(const [x,y] of [[520,150],[1280,140],[600,1070],[1210,1080],[120,560],[1680,600],[380,380],[1420,400],[400,880],[1410,860],[700,300],[1100,290]])tree(x,y,.85+((x+y)%5)*.08);
 for(const [x,y,r] of [[520,560,18],[1290,560,17],[760,980,16],[1050,990,18],[640,240,15],[1170,220,16]])rock(x,y,r);
 // Decorations (no collision).
 for(let i=0;i<70;i++){const x=(97+i*263)%world.w,y=(61+i*389)%world.h;if(Math.hypot(x-H.x,y-H.y)>200&&free(x,y,8))decor.push({kind:i%5===0?'pumpkin':i%3===0?'mushroom':'flowers',x,y,seed:i})}
 for(const [dx,dy] of [[-120,40],[120,40],[-95,-60],[105,-55]])decor.push({kind:'pumpkin',x:H.x+dx,y:H.y+dy,seed:dx+dy});
 const grassTufts=[];for(let i=0;i<420;i++){const x=(100+(i*617%3400))*.5,y=(100+(i*353%2200))*.5;if(Math.hypot(x-H.x,y-H.y)>175&&!trees.some(t=>Math.hypot(t.x-x,t.y-y)<t.radius+14))grassTufts.push({x,y,s:(34+(i*13%24))*.5,r:(i*1.71)%6.28})}
 for(const t of trees){const key=Math.floor(t.x/obstacleCell)+','+Math.floor(t.y/obstacleCell),bucket=obstacleGrid.get(key)||[];bucket.push(t);obstacleGrid.set(key,bucket)}
