 function rosterUpdate(){$('#playerCount').textContent=players.size;for(const target of [roster,$('#rosterInGame')]){target.innerHTML='';for(const p of players.values()){const e=document.createElement('div');e.className='roster-player'+(p.connected?'':' reconnecting');const avatar=document.createElement('span');avatar.className='roster-avatar';avatar.style.setProperty('--chick',p.color);avatar.textContent='🐥';const name=document.createElement('b');name.textContent=p.name;name.style.color=p.color;const status=document.createElement('small');status.textContent=p.connected?'READY · '+(p.via==='relay'?'RELAY':'P2P'):'RECONNECTING…';const kick=document.createElement('button');kick.className='kick-button';kick.textContent='KICK';kick.setAttribute('aria-label','Kick '+p.name);kick.onclick=()=>kickPlayer(p);e.append(avatar,name,status,kick);target.append(e)}}$('#lobbyEmpty')?.classList.toggle('hidden',players.size>0)}
 function kickPlayer(p){kickedIds.add(p.clientId);try{p.conn?.send({type:'kicked'})}catch{}try{p.conn?.close()}catch{}clearTimeout(p.expireTimer);players.delete(p.id);rosterUpdate();toast(p.name+' removed from the lobby')}
