 function renderScores(target){const list=readScores().sort((a,b)=>b.score-a.score).slice(0,10);target.innerHTML=list.length?'<table class="score-table"><thead><tr><th>#</th><th>PLAYER</th><th>BEST</th><th>WAVE</th></tr></thead><tbody>'+list.map((s,i)=>`<tr><td>${i+1}</td><td>${escapeText(s.name)}</td><td>${s.score}</td><td>${s.wave}</td></tr>`).join('')+'</tbody></table>':'<p class="empty-scores">No scores yet. Start a game!</p>'}
