 function updateJoinInfo(){const u=new URL(location.href);u.search='?room='+encodeURIComponent(roomCode)+(params.get('relay')?'&relay='+encodeURIComponent(params.get('relay')):'');u.hash='';$('#roomCode').textContent=roomCode;$('#joinUrl').textContent=u.href;let qr='';try{const q=window.qrcode(0,'M');q.addData(u.href);q.make();qr=q.createDataURL(8,2)}catch{qr='https://api.qrserver.com/v1/create-qr-code/?size=280x280&data='+encodeURIComponent(u.href)}$('#qr').src=qr;$('#qrLarge').src=qr;$('#joinQrBtn').disabled=false}
 function startPeer(){if(typeof Peer==='undefined'){net.p2p='blocked';updateNet();return}try{peer?.destroy()}catch{}const me=new Peer(CFG.peerPrefix+roomCode,peerOptions());peer=me;net.p2p='connecting';me.on('open',()=>{if(peer!==me)return;net.p2p='online';updateNet()});me.on('connection',onIncoming);me.on('disconnected',()=>{if(peer!==me||me.destroyed)return;net.p2p='reconnecting';updateNet();setTimeout(()=>{try{if(!me.destroyed)me.reconnect()}catch{}},1500)});me.on('error',e=>{if(peer!==me)return;if(e.type==='unavailable-id'){setupNetwork();return}if(['network','server-error','socket-error','socket-closed','browser-incompatible'].includes(e.type)){net.p2p='blocked';updateNet();setTimeout(()=>{if(peer===me&&net.p2p==='blocked'&&!me.destroyed){try{me.reconnect()}catch{startPeer()}}},15000)}})}
