 function startMatch(){if(started)return;startMusic();gameOver=false;$('#gameOver').classList.add('hidden');lobby.classList.add('hidden');$('#startBtn').disabled=true;$('#startBtn').textContent='MATCH IN PROGRESS';farmHp=100;wave=0;shots=[];enemyBeams=[];fireballs=[];enemies=[];drops=[];bloodSplats=[];fx=[];remainingToSpawn=0;laserWave=0;turret.active=false;turret.angle=Math.PI/2;for(const p of players.values()){p.hp=100;p.effects={};p.score=0;p.kills=0;p.revive=0;p.deathAt=0;p.move={x:0,y:0};p.fire=false;p.x=H.x-90+[...players.keys()].indexOf(p.id)%4*60+(Math.random()-.5)*20;p.y=H.y+190+(Math.random()-.5)*30;send(p,true)}startWave(1)}
