 function tone(freq=440,duration=.1,type='sine',volume=.035){if(!soundOn||!audio)return;try{const o=audio.createOscillator(),g=audio.createGain(),now=audio.currentTime;o.type=type;o.frequency.setValueAtTime(freq,now);g.gain.setValueAtTime(Math.min(.15,volume*2.2),now);g.gain.exponentialRampToValueAtTime(.001,now+duration);o.connect(g);g.connect(audio.destination);o.start(now);o.stop(now+duration)}catch{}}
 function sweep(f1,f2,duration=.3,type='sine',volume=.05){if(!soundOn||!audio)return;try{const now=audio.currentTime,o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(f1,now);o.frequency.exponentialRampToValueAtTime(f2,now+duration);g.gain.setValueAtTime(volume,now);g.gain.exponentialRampToValueAtTime(.001,now+duration);o.connect(g);g.connect(audio.destination);o.start(now);o.stop(now+duration+.02)}catch{}}
 function chickDeathSound(){if(!soundOn||!audio)return;try{const now=audio.currentTime,o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.setValueAtTime(920,now);o.frequency.exponentialRampToValueAtTime(370,now+.18);o.frequency.exponentialRampToValueAtTime(160,now+.62);g.gain.setValueAtTime(.001,now);g.gain.linearRampToValueAtTime(.09,now+.04);g.gain.exponentialRampToValueAtTime(.001,now+.66);o.connect(g);g.connect(audio.destination);o.start(now);o.stop(now+.67)}catch{}}
 function henCry(){if(!soundOn||!audio)return;try{const now=audio.currentTime,o=audio.createOscillator(),g=audio.createGain();o.type='sawtooth';o.frequency.setValueAtTime(720,now);o.frequency.exponentialRampToValueAtTime(1180,now+.08);o.frequency.exponentialRampToValueAtTime(560,now+.2);o.frequency.exponentialRampToValueAtTime(860,now+.28);o.frequency.exponentialRampToValueAtTime(430,now+.46);g.gain.setValueAtTime(.001,now);g.gain.linearRampToValueAtTime(.045,now+.035);g.gain.setValueAtTime(.04,now+.24);g.gain.exponentialRampToValueAtTime(.001,now+.48);o.connect(g);g.connect(audio.destination);o.start(now);o.stop(now+.49)}catch{}}
 const bgMusic=$('#bgMusic'),musicVolume=$('#musicVolume');bgMusic.volume=.32;function setMusic(enabled){musicOn=enabled;$('#musicBtn').textContent=musicOn?'♫ MUSIC ON':'♫ MUSIC OFF';if(musicOn){musicStarted=true;const playing=bgMusic.play();if(playing?.catch)playing.catch(()=>toast('Tap MUSIC again if playback was blocked'))}else bgMusic.pause()}function startMusic(){if(!musicStarted)setMusic(true)}musicVolume.oninput=()=>{bgMusic.volume=Number(musicVolume.value)/100;$('#musicVolumeLabel').textContent=musicVolume.value+'%'};$('#musicBtn').onclick=()=>setMusic(!musicOn);$('#soundBtn').onclick=async()=>{soundOn=!soundOn;if(soundOn){const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio){soundOn=false;toast('Audio is not supported in this browser')}else{audio=audio||new Audio();if(audio.state==='suspended')await audio.resume()}}$('#soundBtn').textContent=soundOn?'SFX ON':'SFX OFF';tone(620,.12,'triangle')};
