function lockMobileZoom(){
 // iOS Safari ignores user-scalable=no, so block pinch, double-tap and gesture zoom explicitly while keeping text inputs usable.
 const isField=t=>!!t&&!!t.closest&&!!t.closest('input,textarea,select,label');
 for(const type of ['gesturestart','gesturechange','gestureend'])document.addEventListener(type,e=>e.preventDefault(),{passive:false});
 document.addEventListener('touchmove',e=>{if(e.touches.length>1||!isField(e.target))e.preventDefault()},{passive:false});
 document.addEventListener('touchstart',e=>{if(e.touches.length>1)e.preventDefault()},{passive:false});
 let lastTouchEnd=0;document.addEventListener('touchend',e=>{const now=Date.now();if(now-lastTouchEnd<380&&!isField(e.target))e.preventDefault();lastTouchEnd=now},{passive:false});
 document.addEventListener('dblclick',e=>e.preventDefault(),{passive:false});
 document.addEventListener('contextmenu',e=>{if(!isField(e.target))e.preventDefault()});
 // If iOS already zoomed (e.g. while the keyboard was open), snap the viewport back when the field loses focus.
 const vp=document.querySelector('meta[name=viewport]');document.addEventListener('focusout',()=>{if(!vp)return;const c=vp.content;vp.content=c+',width=device-width';setTimeout(()=>{vp.content=c;scrollTo(0,0)},60)});
}
